package org.sleepwell.app;
import android.content.*;import android.hardware.*;import android.os.*;import android.widget.*;import java.util.*;import java.util.function.BooleanSupplier;
/** Shared visible spin task; no sensor starts before the explicit action. */
final class SpinTask implements SensorEventListener,AutoCloseable {
 final SensorManager manager;final Sensor sensor;final SharedPreferences prefs;final String key,token;final BooleanSupplier current;final Runnable complete,fallback;final TextView status;final SpinView view;final Button start;final SpinMotion motion=new SpinMotion();final Handler handler=new Handler(Looper.getMainLooper());boolean closed,registered,delivered;long armed,started,lastFresh;
 static String key(String run,int unit){return ChallengePackState.key(run,unit,0);}
 static boolean math(SharedPreferences prefs,String run,int unit){return key(run,unit).equals(prefs.getString("spinTaskOwner",""))&&prefs.getBoolean("spinTaskMath",false);}
 SpinTask(LinearLayout body,SharedPreferences prefs,String run,int unit,BooleanSupplier current,Runnable complete,Runnable fallback){this.prefs=prefs;this.current=current;this.complete=complete;this.fallback=fallback;key=key(run,unit);token=UUID.randomUUID().toString();boolean prior=math(prefs,run,unit);if(!prefs.edit().putString("spinTaskOwner",key).putString("spinTaskToken",token).putBoolean("spinTaskMath",prior).commit())throw new IllegalStateException("Spin task could not be saved");manager=body.getContext().getSystemService(SensorManager.class);Sensor candidate=manager==null?null:manager.getDefaultSensor(Sensor.TYPE_GAME_ROTATION_VECTOR);sensor=candidate!=null?candidate:manager==null?null:manager.getDefaultSensor(Sensor.TYPE_ROTATION_VECTOR);Design.text(body,"Turn once, slowly",22,600,Design.INK);Design.text(body,"Stand only if safe. Hold the phone upright facing you, keep a finger on each pad, and turn your body once in either direction. Release to reset. Use Math if turning is uncomfortable.",14,400,Design.MUTED);view=new SpinView(body.getContext(),both->{motion.contact(registered&&live()&&both);viewProgress();});body.addView(view,new LinearLayout.LayoutParams(-1,-2));status=Design.text(body,"Rotation sensor stays off until you start",13,500,Design.MUTED);status.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);start=Design.button(body,"Start turn check",true,this::begin);if(sensor==null){start.setEnabled(false);status.setText("Rotation sensor unavailable. Use Math instead.");}Design.button(body,"Use Math instead",false,this::chooseMath);}
 boolean live(){return !closed&&!delivered&&current.getAsBoolean()&&key.equals(prefs.getString("spinTaskOwner",""))&&token.equals(prefs.getString("spinTaskToken",""));}
 void begin(){if(!live()||sensor==null)return;if(!stopSensor()){status.setText("Sensor cleanup failed. Retry or use Math.");return;}motion.reset();armed=SystemClock.elapsedRealtimeNanos();started=SystemClock.elapsedRealtime();lastFresh=0;try{registered=true;if(!manager.registerListener(this,sensor,SensorManager.SENSOR_DELAY_GAME,new Handler(Looper.getMainLooper()))){stopSensor();status.setText("Rotation readings unavailable. Retry or use Math.");return;}motion.contact(view.both);viewProgress();status.setText("Hold both pads and turn slowly with the phone upright.");start.setText("Restart turn check");handler.post(tick);}catch(RuntimeException unavailable){stopSensor();status.setText("Rotation sensor could not start. Retry or use Math.");}}
 final Runnable tick=new Runnable(){public void run(){if(!registered||closed)return;if(!live()){stopSensor();motion.reset();viewProgress();status.setText("Turn check paused. Start again when ready.");return;}long now=SystemClock.elapsedRealtimeNanos();if(SystemClock.elapsedRealtime()-started>=60000||now-(lastFresh==0?armed:lastFresh)>3_000_000_000L){stopSensor();motion.reset();viewProgress();status.setText("No fresh rotation readings or attempt timed out. Retry or use Math.");return;}if(motion.last()>=0&&now-motion.last()>300_000_000L){motion.reset();viewProgress();status.setText("Readings paused. Hold both pads and start your turn again.");}handler.postDelayed(this,100);}};
 @Override public void onSensorChanged(SensorEvent event){if(!registered||!live()||event.values.length<3)return;long now=SystemClock.elapsedRealtimeNanos();if(event.timestamp<armed||event.timestamp>now||now-event.timestamp>250_000_000L||event.accuracy==SensorManager.SENSOR_STATUS_UNRELIABLE){motion.reset();viewProgress();return;}try{for(float value:event.values)if(!Float.isFinite(value))throw new IllegalArgumentException();double xyz=event.values[0]*event.values[0]+event.values[1]*event.values[1]+event.values[2]*event.values[2];if(xyz>1.03)throw new IllegalArgumentException();if(event.values.length>=4){double norm=xyz+event.values[3]*event.values[3];if(norm<.9||norm>1.1)throw new IllegalArgumentException();}float[] matrix=new float[9];SensorManager.getRotationMatrixFromVector(matrix,event.values);double horizontal=Math.hypot(matrix[2],matrix[5]);boolean upright=horizontal>=.75;lastFresh=event.timestamp;boolean ready=motion.sample(event.timestamp,now,Math.atan2(matrix[2],matrix[5]),upright);viewProgress();status.setText(!view.both?"Hold a finger on each pad":!upright?"Keep the screen upright, facing you":"Turn slowly · "+motion.degrees()+"° of 360°");if(ready){if(!stopSensor()){status.setText("Sensor cleanup failed. Retry before continuing.");return;}if(live()){delivered=true;complete.run();}}}catch(RuntimeException invalid){motion.reset();viewProgress();status.setText("Unusable rotation reading. Retry or use Math.");}}
 void viewProgress(){if(view!=null)view.progress(motion.degrees());}
 @Override public void onAccuracyChanged(Sensor sensor,int accuracy){if(accuracy==SensorManager.SENSOR_STATUS_UNRELIABLE){motion.reset();viewProgress();}}
 private void chooseMath(){if(!live())return;if(!stopSensor()){status.setText("Sensor cleanup failed. Retry before choosing Math.");return;}if(!prefs.edit().putBoolean("spinTaskMath",true).commit()){status.setText("Math alternative could not be saved. Try again.");return;}close();fallback.run();}
 private boolean stopSensor(){handler.removeCallbacksAndMessages(null);if(!registered)return true;try{manager.unregisterListener(this);registered=false;motion.contact(false);return true;}catch(RuntimeException failure){return false;}}
 boolean released(){return !registered;}
 @Override public void close(){closed=true;stopSensor();motion.contact(false);view.release();}
}
